//! GLSL / LPIR / LPFX name → `BuiltinId`, per float mode.
//!
//! AUTO-GENERATED by lps-builtins-gen-app. Do not edit manually.
//!
//! Each family has a `_q32_` and an `_f32_` resolver plus a mode-taking facade:
//!
//! - `glsl_{q32,f32}_math_builtin_id` / `glsl_math_builtin_id`: `@glsl::*` scalar imports.
//! - `lpir_{q32,f32}_builtin_id` / `lpir_builtin_id`: `@lpir::*` library ops (e.g. `sqrt`).
//! - `glsl_lpfn_{q32,f32}_builtin_id` / `glsl_lpfn_builtin_id`: `lpfn_*` overloads keyed by parameter types.
//! - `texture_{q32,f32}_builtin_id` / `texture_builtin_id`: `@texture::*` sampler builtins (logical vec4 return via out-pointer).
//! - `vm_{q32,f32}_builtin_id` / `vm_builtin_id`: `@vm::*` context builtins.
//!
//! **A resolver never crosses modes.** In f32 mode only f32 (and
//! mode-independent) ids resolve, and there is no fallback to the Q32 id.
//! That fallback is precisely the failure the wasm f32 bring-up found: a
//! builtin taking a vector receives an `IrType::Pointer`, both sides are
//! `i32`, so a Q32 builtin handed an f32 module's memory reinterprets f32 bit
//! patterns as Q16.16 — wrong answers, no validation error, nothing to catch
//! it. See `docs/design/float.md` §6.
//!
//! Regenerate: `cargo run -p lps-builtins-gen-app` or `scripts/build-builtins.sh`

use super::BuiltinId;
use super::Mode;

/// Parameter types for LPFX overload resolution (matches GLSL, not flattened WASM).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum GlslParamKind {
    Bool,
    Int,
    UInt,
    Float,
    Vec2,
    Vec3,
    Vec4,
    IVec2,
    IVec3,
    IVec4,
    UVec2,
    UVec3,
    UVec4,
    BVec2,
    BVec3,
    BVec4,
}
