/// Resolve for `mode`. Never falls back across modes — see the module docs.
pub fn glsl_math_builtin_id(name: &str, arg_count: usize, mode: Mode) -> Option<BuiltinId> {
    match mode {
        Mode::Q32 => glsl_q32_math_builtin_id(name, arg_count),
        Mode::F32 => glsl_f32_math_builtin_id(name, arg_count),
    }
}

/// Resolve for `mode`. Never falls back across modes — see the module docs.
pub fn lpir_builtin_id(name: &str, arg_count: usize, mode: Mode) -> Option<BuiltinId> {
    match mode {
        Mode::Q32 => lpir_q32_builtin_id(name, arg_count),
        Mode::F32 => lpir_f32_builtin_id(name, arg_count),
    }
}

/// Resolve for `mode`. Never falls back across modes — see the module docs.
pub fn vm_builtin_id(name: &str, arg_count: usize, mode: Mode) -> Option<BuiltinId> {
    match mode {
        Mode::Q32 => vm_q32_builtin_id(name, arg_count),
        Mode::F32 => vm_f32_builtin_id(name, arg_count),
    }
}

/// Resolve for `mode`. Never falls back across modes — see the module docs.
pub fn texture_builtin_id(name: &str, arg_count: usize, mode: Mode) -> Option<BuiltinId> {
    match mode {
        Mode::Q32 => texture_q32_builtin_id(name, arg_count),
        Mode::F32 => texture_f32_builtin_id(name, arg_count),
    }
}

/// Resolve for `mode`. Never falls back across modes — see the module docs.
pub fn glsl_lpfn_builtin_id(name: &str, params: &[GlslParamKind], mode: Mode) -> Option<BuiltinId> {
    match mode {
        Mode::Q32 => glsl_lpfn_q32_builtin_id(name, params),
        Mode::F32 => glsl_lpfn_f32_builtin_id(name, params),
    }
}

#[cfg(test)]
mod glsl_builtin_mapping_tests {
    use super::*;
    use crate::{BuiltinId, Mode};

    #[test]
    fn q32_sin() {
        assert_eq!(
            glsl_q32_math_builtin_id("sin", 1),
            Some(BuiltinId::LpGlslSinQ32)
        );
    }

    #[test]
    fn q32_atan_two_args_is_atan2_import() {
        assert_eq!(
            glsl_q32_math_builtin_id("atan", 2),
            Some(BuiltinId::LpGlslAtan2Q32)
        );
    }

    #[test]
    fn lpir_sqrt() {
        assert_eq!(
            lpir_q32_builtin_id("sqrt", 1),
            Some(BuiltinId::LpLpirFsqrtQ32)
        );
    }

    #[test]
    fn vm_get_fuel() {
        assert_eq!(
            vm_q32_builtin_id("__lp_get_fuel", 0),
            Some(BuiltinId::LpVmGetFuel)
        );
    }

    #[test]
    fn texture_sampler_builtin_id_generation() {
        assert_eq!(
            texture_q32_builtin_id("texture2d_rgba16_unorm", 10),
            Some(BuiltinId::LpTexTexture2dRgba16UnormQ32)
        );
    }

    #[test]
    fn lpfn_fbm_vec2() {
        assert_eq!(
            glsl_lpfn_q32_builtin_id(
                "lpfn_fbm",
                &[GlslParamKind::Vec2, GlslParamKind::Int, GlslParamKind::UInt],
            ),
            Some(BuiltinId::LpLpfnFbm2Q32)
        );
    }

    #[test]
    fn f32_resolvers_exist_for_every_family() {
        assert_eq!(
            lpir_f32_builtin_id("sqrt", 1),
            Some(BuiltinId::LpLpirFsqrtF32)
        );
        assert_eq!(
            glsl_lpfn_f32_builtin_id(
                "lpfn_fbm",
                &[GlslParamKind::Vec2, GlslParamKind::Int, GlslParamKind::UInt],
            ),
            Some(BuiltinId::LpLpfnFbm2F32)
        );
    }

    #[test]
    fn mode_independent_builtins_resolve_in_both_modes() {
        // `lpfn_hash` is integer-in/integer-out and carries no mode suffix.
        // Dropping it from the f32 map would make every hash call in a Float
        // shader unresolvable.
        let params = &[GlslParamKind::UInt, GlslParamKind::UInt];
        assert_eq!(
            glsl_lpfn_q32_builtin_id("lpfn_hash", params),
            Some(BuiltinId::LpLpfnHash1)
        );
        assert_eq!(
            glsl_lpfn_f32_builtin_id("lpfn_hash", params),
            Some(BuiltinId::LpLpfnHash1)
        );
    }

    /// The load-bearing invariant: a resolver never answers with the other
    /// mode's builtin. In f32 mode a Q32 id would reinterpret f32 bit patterns
    /// as Q16.16 through a pointer parameter, which nothing downstream can
    /// detect.
    #[test]
    fn no_resolver_ever_crosses_modes() {
        for id in BuiltinId::all() {
            let name = id.fn_name();
            for argc in 0..=10 {
                for (mode, wrong) in [(Mode::F32, Mode::Q32), (Mode::Q32, Mode::F32)] {
                    for got in [
                        glsl_math_builtin_id(name, argc, mode),
                        lpir_builtin_id(name, argc, mode),
                        vm_builtin_id(name, argc, mode),
                        texture_builtin_id(name, argc, mode),
                    ]
                    .into_iter()
                    .flatten()
                    {
                        assert_ne!(
                            got.mode(),
                            Some(wrong),
                            "{name}/{argc} resolved to {got:?} in the wrong mode"
                        );
                    }
                }
            }
        }
    }
}
